-- Szerepkörös RLS teszt: 4 szerep + szerepkör nélküli. Elvárt eredmény mátrix alapján.
\set ON_ERROR_STOP 0
CREATE TEMP TABLE IF NOT EXISTS res(role text, tbl text, op text, expected bool, got bool);
GRANT ALL ON res TO authenticated;
CREATE OR REPLACE FUNCTION try(sql text) RETURNS bool LANGUAGE plpgsql AS $$ DECLARE n int; BEGIN EXECUTE sql; GET DIAGNOSTICS n = ROW_COUNT; RETURN n > 0; EXCEPTION WHEN insufficient_privilege OR others THEN RETURN false; END $$;
GRANT EXECUTE ON FUNCTION try(text) TO authenticated;
